<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); ?>
<section class="public-news"><header><p class="eyebrow"><?= $e($championship['name']) ?></p><h1>Notícias</h1><p>Atualizações, bastidores e histórias que fazem parte do campeonato.</p></header><form class="filter-bar" method="get" action="<?= $e($base . '/noticias') ?>"><label>Buscar notícias <input name="q" value="<?= $e($search) ?>" placeholder="Digite palavras-chave"></label><button type="submit">Buscar</button></form>
<div class="news-grid"><?php foreach ($items as $item): ?><article class="news-card"><?php if (!empty($item['cover_image_path'])): ?><img src="<?= $e($base . '/noticias/' . $item['slug'] . '/capa') ?>" alt="Capa: <?= $e($item['title']) ?>"><?php else: ?><span class="news-card-fallback" data-icon="newspaper" aria-hidden="true"></span><?php endif; ?><p class="eyebrow"><?= !empty($item['featured']) ? 'Em destaque' : 'Notícia' ?></p><h2><a href="<?= $e($base . '/noticias/' . $item['slug']) ?>"><?= $e($item['title']) ?></a></h2><p><?= $e($item['summary']) ?></p><small><?= $e(substr((string) $item['published_at'], 0, 10)) ?> · <?= $e($item['author_name']) ?></small></article><?php endforeach; ?><?php if (!$items): ?><p>Nenhuma notícia publicada.</p><?php endif; ?></div>
<?php if ($pages > 1): ?><nav class="pagination" aria-label="Paginação"><?php for ($index = 1; $index <= $pages; $index++): ?><a class="<?= $index === $page ? 'active' : '' ?>" href="<?= $e($base . '/noticias?page=' . $index . '&q=' . urlencode($search)) ?>"><?= $index ?></a><?php endfor; ?></nav><?php endif; ?></section>
